<# Focused action dock acceptance. Owned Windows fixtures/messages only. #>
param([string]$BuildDirectory,[string]$ResultDirectory)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;$overall=[Diagnostics.Stopwatch]::StartNew()
if(-not $BuildDirectory){$BuildDirectory=Join-Path $root 'build\release'}
if(-not $ResultDirectory){$ResultDirectory=Join-Path $root ('build\action_dock\'+[DateTime]::UtcNow.ToString('yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N'))}
if(Test-Path $ResultDirectory){throw 'Use a fresh evidence directory'}
New-Item -ItemType Directory $ResultDirectory|Out-Null
$left=Join-Path $ResultDirectory 'fixtures\left';$right=Join-Path $ResultDirectory 'fixtures\right';$template=Join-Path $ResultDirectory 'fixtures\empty-template';New-Item -ItemType Directory $left,$right,$template|Out-Null
[IO.File]::WriteAllText((Join-Path $left 'notes.md'),"# Notes`nleft content`n");[IO.File]::Copy((Join-Path $left 'notes.md'),(Join-Path $left 'copy.md'));[IO.File]::WriteAllText((Join-Path $right 'other.md'),"# Notes`nright content`n")
$duplicateRoot=Join-Path $ResultDirectory 'fixtures\duplicate-roots';New-Item -ItemType Directory $duplicateRoot|Out-Null
for($i=0;$i -lt 17;$i++){$folder=Join-Path $duplicateRoot ('dup-{0:d2}' -f $i);New-Item -ItemType Directory $folder|Out-Null;[IO.File]::WriteAllText((Join-Path $folder 'same.txt'),"Dock duplicate fixture`n")}
foreach($name in @('blocked-a.txt','blocked-b.txt')){[IO.File]::WriteAllText((Join-Path $duplicateRoot $name),"Ineligible file root`n")}
$git=Join-Path $env:ProgramFiles 'Git\cmd\git.exe';$pi=[Diagnostics.ProcessStartInfo]::new($git);$pi.UseShellExecute=$false;$pi.CreateNoWindow=$true;$pi.RedirectStandardOutput=$true;$pi.RedirectStandardError=$true;foreach($arg in @('-C',$left,'init','-b','main',('--template='+$template))){[void]$pi.ArgumentList.Add($arg)};$process=[Diagnostics.Process]::Start($pi);$o=$process.StandardOutput.ReadToEndAsync();$e=$process.StandardError.ReadToEndAsync();if(-not $process.WaitForExit(30000)){$process.Kill($true);throw 'Owned Git fixture timed out'};$code=$process.ExitCode;$process.Dispose();if($code){throw ('Owned Git fixture failed: '+$e.Result)}
$registry=Get-Content (Join-Path $PSScriptRoot 'native-impact.json') -Raw|ConvertFrom-Json;$sources=[ordered]@{}
foreach($name in @('app/actiondock.h','app/actiondock.c','app/fpdemo.c','app/fn.h','app/fn.c','app/menu.h','app/menu.c','tests/actiondock_tests.c','tests/actiondock_host_tests.c','tests/action_dock.ps1','tools/build-actiondock.py','build.ps1','tests/native-impact.json')){$sources[$name]=(Get-FileHash (Join-Path $root $name) -Algorithm SHA256).Hash.ToLowerInvariant()}
$selectors=@($registry.selectors.psobject.Properties|Where-Object {$_.Name.StartsWith('tests/actiondock_tests.c::') -or $_.Name.StartsWith('tests/actiondock_host_tests.c::')});foreach($selector in $selectors){foreach($name in $selector.Value.sources){$path=Join-Path $root $name;if(Test-Path $path -PathType Leaf){$sources[$name]=(Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant()}}}
$images=[ordered]@{};foreach($name in @('actiondock_tests.exe','actiondock_host_tests.exe','folderwing.exe','folderwing-content.exe','folderwing-diff.exe','folderwing-duplicates.exe','folderwing-space.exe','folderwing-git.exe','folderwing-terminal.exe','folderwing-operations.exe','folderwing-text.exe','direct-client.exe')){$images[$name]=(Get-FileHash (Join-Path $BuildDirectory $name) -Algorithm SHA256).Hash.ToLowerInvariant()}
$os=Get-CimInstance Win32_OperatingSystem;$profile=[ordered]@{workers=1;pwsh=$PSVersionTable.PSVersion.ToString();os=[Environment]::OSVersion.VersionString;free_memory_kib=$os.FreePhysicalMemory;cpu_load=@(Get-CimInstance Win32_Processor|ForEach-Object LoadPercentage);cache='uncontrolled development host';containers='unchanged; unused';network='none';external_services='none'};$setupMs=$overall.Elapsed.TotalMilliseconds
$input=[ordered]@{schema='openpilot-action-dock-input/v1';nodeids=@($selectors|ForEach-Object Name);sources=$sources;images=$images;profile=$profile;runner='tests/action_dock.ps1';fixtures='owned Windows panes, local Git repo, selection/menu oracles and asynchronous settings file';full_suite=$false}
$json=$input|ConvertTo-Json -Depth 8 -Compress;$key=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($json))).ToLowerInvariant();[IO.File]::WriteAllText((Join-Path $ResultDirectory 'INPUT.json'),$json)
foreach($lane in @('actiondock_tests','actiondock_host_tests')){
 $pi=[Diagnostics.ProcessStartInfo]::new((Join-Path $BuildDirectory ($lane+'.exe')));$pi.UseShellExecute=$false;$pi.CreateNoWindow=$true;$pi.RedirectStandardOutput=$true;$pi.RedirectStandardError=$true
 if($lane -eq 'actiondock_host_tests'){$local=Join-Path $ResultDirectory 'direct-localappdata';New-Item -ItemType Directory $local|Out-Null;$pi.Environment['LOCALAPPDATA']=$local;$pi.Environment['OPENPILOT_DOCK_DUPLICATE_FIXTURE']=$duplicateRoot;foreach($arg in @($left,$right,$ResultDirectory)){[void]$pi.ArgumentList.Add($arg)}}
 $watch=[Diagnostics.Stopwatch]::StartNew();$process=[Diagnostics.Process]::Start($pi);$o=$process.StandardOutput.ReadToEndAsync();$e=$process.StandardError.ReadToEndAsync();$timedOut=-not $process.WaitForExit(120000);if($timedOut){$process.Kill($true);$process.WaitForExit()};$watch.Stop();$exit=$(if($timedOut){124}else{$process.ExitCode});$process.Dispose()
 [IO.File]::WriteAllText((Join-Path $ResultDirectory ($lane+'-stdout.txt')),$o.Result);[IO.File]::WriteAllText((Join-Path $ResultDirectory ($lane+'-stderr.txt')),$e.Result)
 @{outcome=$(if($exit -eq 0){'passed'}else{'failed'});exit_code=$exit;input_key=$key;elapsed_ms=$watch.Elapsed.TotalMilliseconds;workers=1;physical_input=$false;full_suite=$false}|ConvertTo-Json|Set-Content (Join-Path $ResultDirectory ($lane+'.json'))
 Write-Output $o.Result;if($exit){throw ('Action dock lane failed: '+$lane)}
}
@{outcome='passed';fixtures='retained under this fresh evidence directory';setup_ms=$setupMs;wall_ms=$overall.Elapsed.TotalMilliseconds;wsl_stopped=$false;docker_stopped=$false}|ConvertTo-Json|Set-Content (Join-Path $ResultDirectory 'RESULT.json')
